import { ChevronLeft, ChevronRight, IdCard, Shuffle } from 'lucide-react';
import type { Player } from '@/types/player';
import InLeague from '@/components/InLeague';
import { getLegacyTier, isHallOfFamer } from '@/config/stats';
import { SIM_MIN_GAMES } from '@/config/advanced';
import type { Family } from '@/config/families';
import { findNFLTeam } from '@/utils/nflTeams';
import { POSITION_NAMES } from '@/utils/playerMeta';
import { useJerseyNumbers } from '@/utils/jerseys';
import { normalizeName, signatureTeamOf, usePlayerExtras } from '@/utils/playerExtras';
import PlayerSearchSelect from '../../PlayerSearchSelect';
import ProPlayerBanner from '../../brand/ProPlayerBanner';
import TeamLogo from '../../brand/TeamLogo';
import { bannerFor, useSeasonView } from '../../player/seasonView';
import GameSprite from '../../GameSprite';
import TributeButton from '../../tribute/TributeButton';
import { RetiredHangers } from '../../teams/RetiredBadge';
import { keyOf } from '../records';
import { openTeamPage } from '@/utils/teamSearch';
import { DraftPills } from '@/components/player/DraftTiles';
import { BioPills } from '@/components/player/BioTiles';
import '@/components/player/playerCard.css';
import './ddHero.css';
import { SmallSampleChip } from './ddParts';
import { displayName } from '@/utils/displayName';
import { IS_NFL } from '@/config/edition';
import { useBlackInk } from '@/utils/seasonBoards';

const ctl =
  'inline-flex h-12 items-center justify-center gap-1.5 rounded-md border border-line bg-night/60 px-3 font-display text-sm font-bold uppercase tracking-wide text-muted-foreground transition-colors hover:bg-panel-2 hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-gold disabled:opacity-40';

interface Props {
  player: Player;
  options: Player[];
  ovr: number | undefined;
  /** Tooltip on the OVR badge: which rating it is (this season / career) */
  ovrTitle?: string;
  ovrLabel?: string;
  ovrAlt?: { label: string; value: number; title?: string } | null;
  wide: boolean;
  onChoose: (key: string) => void;
  onRandom: () => void;
  prev: Player | null;
  next: Player | null;
  onOpenCard: () => void;
  /** His play-style family (config/families.ts), shown as a chip; clicking it opens the families map. */
  family?: Family | null;
  onFamily?: () => void;
}

/** Search + navigation bar and the full-width team-themed banner. */
const DdHero = ({ player, options, ovr, ovrTitle, ovrLabel, ovrAlt, wide, onChoose, onRandom, prev, next, onOpenCard, family, onFamily }: Props) => {
  const { numberFor } = useJerseyNumbers();
  const ink = useBlackInk(IS_NFL ? keyOf(player) : undefined);
  const seasonView = useSeasonView(player);
  const bannerNums = bannerFor(player, seasonView);
  const extras = usePlayerExtras();
  // The banner wears his signature team (where he was best known); the franchise chips list them all
  const club = signatureTeamOf(extras, player);
  const team = findNFLTeam(club);
  // NFL edition: the Hall of Fame is real membership (the banner's badge), not a Career Legacy tier
  const tier = IS_NFL ? null : getLegacyTier(player.careerLegacy);
  const known = extras.franchises[normalizeName(player.name)] ?? [];
  const franchises = known.length ? known : player.team ? [player.team] : [];

  return (
    <div className="space-y-3">
      <div className="flex flex-col gap-2 sm:flex-row sm:items-center">
        <div className="min-w-0 flex-1 [&_[role=combobox]]:h-12 [&_[role=combobox]]:text-base">
          <PlayerSearchSelect showOvr players={options} value={keyOf(player)} onValueChange={(v) => v && onChoose(v)} placeholder="Search any league player..." ariaLabel="Deep Dive player" />
        </div>
        <div className="grid grid-cols-[1fr_auto_auto] gap-2 sm:flex">
          <button type="button" onClick={onRandom} className={ctl}>
            <Shuffle className="h-4 w-4" aria-hidden="true" />
            Random
          </button>
          <button
            type="button"
            onClick={() => prev && onChoose(keyOf(prev))}
            disabled={!prev}
            className={ctl}
            aria-label={prev ? `Previous ${player.position} by OVR: ${displayName(prev.name)}` : 'No previous player'}
            title={prev ? `Prev ${player.position}: ${displayName(prev.name)}` : undefined}
          >
            <ChevronLeft className="h-4 w-4" aria-hidden="true" />
            <span className="hidden md:inline">Prev</span>
          </button>
          <button
            type="button"
            onClick={() => next && onChoose(keyOf(next))}
            disabled={!next}
            className={ctl}
            aria-label={next ? `Next ${player.position} by OVR: ${displayName(next.name)}` : 'No next player'}
            title={next ? `Next ${player.position}: ${displayName(next.name)}` : undefined}
          >
            <span className="hidden md:inline">Next</span>
            <ChevronRight className="h-4 w-4" aria-hidden="true" />
          </button>
        </div>
      </div>

      <div className="relative">
      <button
        type="button"
        onClick={onOpenCard}
        aria-label={`Open ${displayName(player.name)}'s player card`}
        className="block w-full rounded-xl text-left focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-gold focus-visible:ring-offset-2 focus-visible:ring-offset-background"
      >
        <ProPlayerBanner
          size={wide ? 'hero' : 'card'}
          name={displayName(player.name)}
          nickname={player.nickname}
          position={player.position}
          team={team ?? player.team}
          number={numberFor(player)}
          ovr={ovr ?? null}
          ovrTitle={ovrTitle}
          ovrLabel={ovrLabel}
          ovrAlt={ovrAlt}
          hallOfFamer={isHallOfFamer(player)}
          // the hanging banners (RetiredHangers below) carry the retired number
          retiredBy={null}
          // on a phone the position alone, so the retired banners in the top right corner stay clear of it
          eyebrow={wide ? `${POSITION_NAMES[player.position]} · Scouting report` : POSITION_NAMES[player.position]}
          nameAs="h1"
          interactive
          figure={<GameSprite player={player} team={club} kind="figure" size={wide ? 'l' : 'm'} showKit />}
          statsKicker={bannerNums.kicker}
          stats={[...bannerNums.stats, ...(ink > 0 && !seasonView ? [{ label: 'Black ink', value: ink }] : [])]}
        />
      </button>
      {/* his retired number hangs from the hero's top edge, one banner per club (tap: their rafters) */}
      <RetiredHangers player={player} className="dd-hangers" />
      </div>

      {/* owner: "the little pills on deep dive stack oddly": two tidy rows of one pill style, his facts then his path
          (college → draft → clubs), the card hint at the end of the first on desktop only */}
      <div className="dd-facts">
        {/* His Player Tribute, when one has been written */}
        <TributeButton playerKey={keyOf(player)} label="Read his tribute" className="h-8 border border-gold/60 bg-gold/10 px-2.5 text-sm text-gold hover:bg-gold/20" />
        <InLeague player={player} />
        {tier ? (
          <span className="lamp">
            HOF <b>{tier.label}</b>
          </span>
        ) : null}
        <span className="lamp">
          GP <b>{player.games}</b>
        </span>
        {player.games < SIM_MIN_GAMES && <SmallSampleChip />}
        {family && (
          <button
            type="button"
            onClick={onFamily}
            disabled={!onFamily}
            title={`${displayName(family.name)} (${family.members.length} ${player.position}s): ${family.definition}. Show the families map.`}
            className="lamp cursor-pointer border focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-gold disabled:cursor-default"
            style={{ borderColor: family.color }}
          >
            Family <b style={{ color: family.color }}>{displayName(family.name)}</b>
          </button>
        )}
        {IS_NFL && <BioPills player={player} />}
        <span className="dd-facts__hint">
          <IdCard className="h-3.5 w-3.5" aria-hidden="true" />
          Tap the banner for the full player card
        </span>
      </div>
      <div className="dd-path" aria-label="College, draft and clubs">
        <DraftPills playerKey={keyOf(player)} />
        {franchises.length > 0 && (
          <ul className="contents" aria-label="Franchise history">
            {franchises.map((f, i) => (
              <li key={`${f}-${i}`}>
                <button
                  type="button"
                  disabled={!findNFLTeam(f)}
                  onClick={() => openTeamPage(findNFLTeam(f)!.name, { tab: 'franchise' })}
                  title={`Open the ${findNFLTeam(f)?.fullName ?? f} team page`}
                  className="ix-card inline-flex cursor-pointer items-center gap-1 rounded-full border border-line bg-panel px-2 py-0.5 text-xs focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-gold disabled:cursor-default"
                >
                  <TeamLogo team={f} size={16} decorative backed />
                  <span>{findNFLTeam(f)?.name ?? f}</span>
                </button>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
};

export default DdHero;
